WORKING_DIR = Path('/kaggle/working')
SUB_ROOT = WORKING_DIR / 'submissions'
TASK_IDS = ['fastapi_15588', 'fastapi_15589', 'rich_3882', 'rich_3470']
CONFIGS = ['1a']
